CREATE POLICY pos_venda_foto_inserir ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='consultora-pos-venda' AND (storage.foldername(name))[1]=auth.uid()::text AND public.has_role(auth.uid(),'consultora') AND lower(storage.extension(name)) IN ('jpg','jpeg','png','webp'));
CREATE POLICY pos_venda_foto_ler ON storage.objects FOR SELECT TO authenticated USING (bucket_id='consultora-pos-venda' AND ((storage.foldername(name))[1]=auth.uid()::text OR ((public.has_role(auth.uid(),'master') OR public.has_role(auth.uid(),'qualidade')) AND EXISTS(SELECT 1 FROM public.consultora_pos_venda r WHERE r.fotos ? name))));